const safeAll = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };

// Optional config block: config.contact_finder. Safe defaults if it is missing.
let cfg = {};
try { cfg = JSON.parse((safeAll('Fetch Config').find(r => r && r.key === 'config_json') || {}).value || '{}'); } catch (e) { cfg = {}; }
const F = Object.assign({ enabled: true, max_accounts_per_run: 3, max_results: 8, search_depth: 'basic', yc_lookup: true }, cfg.contact_finder || {});

if (F.enabled === false) return [{ json: { __skipped: 'contact_finder disabled by config' } }];

const norm = (d) => String(d || '').toLowerCase().trim().replace(/^www\./, '');

// Any domain already in contact_results (people or a no-result marker) is never searched again
const done = new Set(safeAll('Fetch Contact Results').map(r => norm(r.domain)).filter(d => d && d !== '__placeholder__'));

// Account facts used to check that a person really belongs to THIS company
const acct = {};
for (const a of safeAll('Fetch Accounts')) if (a && a.domain) acct[norm(a.domain)] = a;

const queue = safeAll('Fetch Contacts Queue').filter(r => r && r.domain && r.account_id);
const seen = new Set();
const todo = [];
for (const r of queue) {
  const d = norm(r.domain);
  if (!d || done.has(d) || seen.has(d)) continue;
  if (String((acct[d] || {}).status || '').toLowerCase() === 'rejected') continue;   // you rejected this account
  seen.add(d);
  todo.push(r);
}

const cap = Math.max(1, Math.min(10, Number(F.max_accounts_per_run || 3)));   // at most 1 Tavily credit per account
const batch = todo.slice(0, cap);

if (!batch.length) return [{ json: { __skipped: 'contact_finder: nothing to look up', queue_rows: queue.length, already_done: done.size } }];

const slugify = s => String(s || '').toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

return batch.map(r => {
  const d = norm(r.domain);
  const a = acct[d] || {};
  const rawName = String(r.company_name || '').trim();
  // HN accounts carry the domain as their name. Use the first label instead ("goareo.com" -> "goareo").
  const company = (!rawName || /\.[a-z]{2,}$/i.test(rawName)) ? d.split('.')[0] : rawName;
  const loc = String(a.location_raw || '').split(';')[0];
  const city = /remote/i.test(loc) ? '' : loc.split(',')[0].trim();
  // Guesses for the company's Y Combinator page name. A guess only counts if that page lists this exact website.
  const s1 = slugify(company), s2 = d.split('.')[0];
  const ycSlugs = F.yc_lookup === false ? [] : Array.from(new Set([s1, s2, s1.replace(/-/g, '')].filter(Boolean)));
  return {
    json: {
      domain: d,
      account_id: String(r.account_id),
      company,
      source: String(a.source || ''),
      country: String(a.country || '').trim(),
      city,
      yc_slugs: ycSlugs,
      // Plain-language query. Tavily is a semantic search, so quotes and OR operators return nothing.
      query: company + ' founder CEO co-founder head of sales LinkedIn profile',
      max_results: Math.max(3, Math.min(20, Number(F.max_results || 8))),
      search_depth: F.search_depth === 'advanced' ? 'advanced' : 'basic',
      include_domains: F.restrict_to_linkedin === false ? [] : ['linkedin.com']
    }
  };
});

const safeAll = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };

// Only the lookups that the YC step could not answer reach the search, in this order.
const lookups = safeAll('YC Founders').filter(l => l && l.query && l.domain);
const MAX_PER_COMPANY = 3;
const nowIso = new Date().toISOString();
const C = { lookups: lookups.length, responses: 0, empty: 0, results: 0, not_profile: 0, wrong_company: 0, wrong_location: 0, no_role: 0, dup: 0, kept: 0, kept_unverified: 0, no_result_accounts: 0, credits: 0 };

const esc = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const hasWord = (text, w) => new RegExp('(^|[^a-z0-9])' + esc(String(w).toLowerCase()) + '([^a-z0-9]|$)').test(String(text).toLowerCase());

// Roles worth contacting, best first. Only these are written.
const ROLE_RE = [
  /\b(?:co-?founder|founder|founding partner)\b(?:\s*(?:&|and|,|\/)\s*(?:ceo|cto|coo|cro|cmo|managing director))?/i,
  /\b(?:ceo|chief executive officer|managing director|managing partner|owner)\b/i,
  /\b(?:chief revenue officer|cro|head of rev(?:enue)? ?ops|revops (?:lead|manager)|revenue operations (?:lead|manager|director)|head of revenue operations)\b/i,
  /\b(?:head of sales|vp (?:of )?sales|sales director|director of sales|head of growth|growth lead|head of marketing|cmo|head of operations|cto|chief technology officer)\b/i,
  /\b(?:sales operations|marketing operations|gtm|go-to-market)\b[a-z ]{0,20}(?:lead|manager|director|engineer)?/i
];
function findRole(text) {
  const t = String(text || '');
  for (let i = 0; i < ROLE_RE.length; i++) { const m = t.match(ROLE_RE[i]); if (m) return { role: m[0].replace(/\s+/g, ' ').trim(), rank: i }; }
  return null;
}

function cleanUrl(u) {
  const m = String(u || '').match(/^https?:\/\/([a-z]{2,3}\.)?linkedin\.com\/in\/([^/?#]+)/i);
  return m ? 'https://www.linkedin.com/in/' + m[2].toLowerCase() : '';
}

// ---- location check: a company name alone is not proof, many companies share a name ----
const ALIASES = {
  'united kingdom': ['united kingdom', 'england', 'scotland', 'wales', 'london', 'manchester', ' uk'],
  'united states': ['united states', 'usa', 'california', 'new york', 'san francisco', 'texas', 'boston', 'seattle', 'chicago', 'los angeles', 'florida', 'colorado', 'utah', 'washington'],
  'france': ['france', 'paris', 'lyon'], 'germany': ['germany', 'berlin', 'munich', 'hamburg', 'deutschland'],
  'netherlands': ['netherlands', 'amsterdam', 'rotterdam'], 'spain': ['spain', 'madrid', 'barcelona'],
  'portugal': ['portugal', 'lisbon', 'porto'], 'ireland': ['ireland', 'dublin'], 'sweden': ['sweden', 'stockholm'],
  'denmark': ['denmark', 'copenhagen'], 'switzerland': ['switzerland', 'zurich', 'geneva'], 'austria': ['austria', 'vienna'],
  'italy': ['italy', 'milan', 'rome'], 'belgium': ['belgium', 'brussels'], 'poland': ['poland', 'warsaw'],
  'estonia': ['estonia', 'tallinn'], 'united arab emirates': ['united arab emirates', 'dubai'],
  'canada': ['canada', 'toronto', 'vancouver'], 'india': ['india', 'bangalore', 'bengaluru', 'mumbai'],
  'australia': ['australia', 'sydney', 'melbourne'], 'singapore': ['singapore'], 'israel': ['israel', 'tel aviv'], 'brazil': ['brazil']
};
// 'match' = the profile mentions the company's country or city. 'mismatch' = it mentions another country and not ours.
// 'unknown' = no location on either side.
function locationCheck(l, text) {
  const t = ' ' + String(text || '').toLowerCase() + ' ';
  const country = String(l.country || '').toLowerCase().trim();
  const city = String(l.city || '').toLowerCase().trim();
  const mine = (ALIASES[country] || (country ? [country] : [])).concat(city.length >= 3 ? [city] : []);
  if (!mine.length) return 'unknown';
  if (mine.some(w => t.includes(w))) return 'match';
  for (const k of Object.keys(ALIASES)) { if (k !== country && ALIASES[k].some(w => t.includes(w))) return 'mismatch'; }
  return 'unknown';
}

const rows = [];
const answered = new Set();

const inputs = $input.all();
for (let i = 0; i < inputs.length; i++) {
  const res = inputs[i].json || {};
  // Match a response to its account by position. Tavily rewrites the query it echoes back, so text matching is unsafe.
  const l = inputs.length === lookups.length
    ? lookups[i]
    : lookups.find(x => String(res.query || '').toLowerCase().startsWith(String(x.company).toLowerCase() + ' '));
  if (!l || !Array.isArray(res.results)) continue;       // failed request: no row, so it retries next run
  C.responses++;
  C.credits += Number((res.usage || {}).credits || 1);
  // Zero results is a search problem, not a "nobody works there" answer. No marker, so it retries next run.
  if (!res.results.length) { C.empty++; continue; }
  answered.add(l.domain);

  const people = [];
  const seenUrl = new Set();
  for (const r of res.results) {
    C.results++;
    const url = cleanUrl(r.url);
    if (!url) { C.not_profile++; continue; }
    if (seenUrl.has(url)) { C.dup++; continue; }

    const title = String(r.title || '').replace(/\s*\|\s*LinkedIn.*$/i, '').trim();
    const content = String(r.content || '').replace(/[ \t]+/g, ' ').trim();   // keep line breaks

    // Company gate: the company must be in the profile title, or be a CURRENT job in the snippet ("at Crono (Jul 2022 to present)").
    const co = esc(String(l.company).toLowerCase());
    const currentJob = new RegExp('(?:\\bat|@)\\s+' + co + '\\s*\\([^)\\n]{0,40}present', 'i').test(content);
    if (!hasWord(title, l.company) && !currentJob) { C.wrong_company++; continue; }

    // Location gate. A profile that mentions the company's own domain is accepted outright.
    const mentionsDomain = (title + ' ' + content).toLowerCase().includes(l.domain);
    const loc = mentionsDomain ? 'match' : locationCheck(l, title + ' ' + content);
    if (loc === 'mismatch') { C.wrong_location++; continue; }

    const parts = title.split(/\s+[-–—]\s+/).map(s => s.trim()).filter(Boolean);
    const name = (parts[0] || '').replace(/\s*\(.*?\)\s*/g, ' ').replace(/,.*$/, '').trim();
    if (!name || name.split(' ').length < 2 || name.length > 60) { C.not_profile++; continue; }

    // Role: from the title's middle part first, then from the snippet near the company name
    const hit = findRole(parts.slice(1).join(' - ')) || findRole(content.slice(0, 300));
    if (!hit) { C.no_role++; continue; }

    seenUrl.add(url);
    people.push({ name, title: hit.role, rank: hit.rank, url, score: Number(r.score || 0), verified: loc === 'match' });
  }

  // Location-confirmed people first, then by role, then by search score
  people.sort((a, b) => (b.verified - a.verified) || a.rank - b.rank || b.score - a.score);
  const keep = people.slice(0, MAX_PER_COMPANY);

  if (!keep.length) {
    C.no_result_accounts++;
    // Marker row: stops this account being searched again. Empty full_name means the main workflow ignores it.
    rows.push({ json: { domain: l.domain, account_id: l.account_id, full_name: '', title: 'NO_RESULT', email: '', email_status: 'not_found',
      person_linkedin: '', provider: 'tavily_search', credits_used: 1, enriched_at: nowIso } });
    continue;
  }
  for (const p of keep) {
    C.kept++; if (!p.verified) C.kept_unverified++;
    // "tavily_unverified" = the name matched but nothing confirmed it is this company. It is flagged on the draft.
    rows.push({ json: { domain: l.domain, account_id: l.account_id, full_name: p.name, title: p.title, email: '', email_status: 'not_found',
      person_linkedin: p.url, provider: p.verified ? 'tavily_search' : 'tavily_unverified', credits_used: Number((1 / keep.length).toFixed(2)), enriched_at: nowIso } });
  }
}

const failed = lookups.filter(l => !answered.has(l.domain)).map(l => l.domain);
const note = 'finder stats: lookups=' + C.lookups + ' responses=' + C.responses + ' credits=' + C.credits + ' empty=' + C.empty + ' results=' + C.results +
  ' not_profile=' + C.not_profile + ' wrong_company=' + C.wrong_company + ' wrong_location=' + C.wrong_location + ' no_role=' + C.no_role +
  ' kept=' + C.kept + ' kept_unverified=' + C.kept_unverified + ' no_result_accounts=' + C.no_result_accounts + (failed.length ? ' retry_next_run=' + failed.join(',') : '');

// The stats item goes last. The Filter node after this one keeps only rows with a domain.
return rows.concat([{ json: { __stats: note } }]);

// For each lookup, try the company's public Y Combinator page first. It lists the founders by name with their
// LinkedIn links, so there is no guessing. Free, no key. Anything not found here continues to the Tavily search.
const lookups = $input.all().map(i => i.json).filter(l => l && l.query && l.domain);
if (!lookups.length) return $input.all();   // pass skip markers through untouched

const MAX_FOUNDERS = 3;
const nowIso = new Date().toISOString();
const sleep = ms => new Promise(r => setTimeout(r, ms));
const C = { lookups: lookups.length, yc_found: 0, yc_people: 0, not_on_yc: 0, wrong_site: 0, no_linkedin: 0, to_search: 0, requests: 0, errors: 0 };

const normDomain = (raw) => String(raw || '').trim().toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split(/[\/?#]/)[0];
const decodeAttr = s => String(s).replace(/&quot;/g, '"').replace(/&#0?39;|&#x27;|&apos;/gi, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const liUrl = u => {
  const m = String(u || '').match(/linkedin\.com\/in\/([^\/?#\s]+)/i);
  if (!m) return '';
  let slug = m[1]; try { slug = decodeURIComponent(slug); } catch (e) { /* keep as is */ }
  return 'https://www.linkedin.com/in/' + slug.toLowerCase();
};
// The page embeds its data as JSON in a data-page attribute: props.company.founders[]
const parseYc = (html) => {
  const m = String(html || '').match(/data-page="([^"]+)"/);
  if (!m) return null;
  let j; try { j = JSON.parse(decodeAttr(m[1])); } catch (e) { return null; }
  const c = ((j || {}).props || {}).company;
  if (!c || !Array.isArray(c.founders)) return null;
  return { website: normDomain(c.website), founders: c.founders };
};

const getPage = async (slug) => {
  C.requests++;
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://www.ycombinator.com/companies/' + encodeURIComponent(slug),
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; personal-gtm-engine/3.0; contact research)', 'Accept': 'text/html' },
      json: false, timeout: 15000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    if (res && typeof res === 'object' && 'body' in res) return { status: Number(res.statusCode || res.status || 0), html: typeof res.body === 'string' ? res.body : '' };
    return { status: 200, html: typeof res === 'string' ? res : '' };
  } catch (e) {
    const m = String((e && e.message) || e).match(/status code (\d{3})/i);
    if (!m) C.errors++;
    return { status: m ? Number(m[1]) : 0, html: '' };
  }
};

const out = [];
let first = true;
for (const l of lookups) {
  let page = null, sawOther = false;
  for (const slug of (Array.isArray(l.yc_slugs) ? l.yc_slugs : [])) {
    if (!first) await sleep(500);
    first = false;
    const r = await getPage(slug);
    if (r.status !== 200) continue;
    const p = parseYc(r.html);
    if (!p) continue;
    if (p.website === l.domain) { page = p; break; }
    sawOther = true;    // a different company with the same name: ignore it
  }

  if (!page) {
    if (sawOther) C.wrong_site++; else C.not_on_yc++;
    C.to_search++;
    out.push({ json: l });           // still has "query", so it goes to the Tavily search
    continue;
  }

  const people = page.founders
    .filter(f => f && f.is_active !== false && String(f.full_name || '').trim())
    .map(f => ({ name: String(f.full_name).trim(), title: String(f.title || '').trim() || 'Founder', url: liUrl(f.linkedin_url) }));
  const usable = people.filter(p => p.url).slice(0, MAX_FOUNDERS);
  C.no_linkedin += people.length - people.filter(p => p.url).length;

  if (!usable.length) { C.to_search++; out.push({ json: l }); continue; }

  C.yc_found++;
  for (const p of usable) {
    C.yc_people++;
    out.push({ json: { domain: l.domain, account_id: l.account_id, full_name: p.name, title: p.title, email: '', email_status: 'not_found',
      person_linkedin: p.url, provider: 'yc_directory', credits_used: 0, enriched_at: nowIso } });
  }
}

const note = 'yc founders: lookups=' + C.lookups + ' found_on_yc=' + C.yc_found + ' people=' + C.yc_people + ' not_on_yc=' + C.not_on_yc +
  ' same_name_other_company=' + C.wrong_site + ' founder_without_linkedin=' + C.no_linkedin + ' sent_to_search=' + C.to_search +
  ' page_requests=' + C.requests + ' errors=' + C.errors;
return out.concat([{ json: { __stats: note } }]);
